/**
 * @module
 * Body Limit Middleware for Hono.
 */

import type { Context } from '../../context'
import { HTTPException } from '../../http-exception'
import type { MiddlewareHandler } from '../../types'

const ERROR_MESSAGE = 'Payload Too Large'

type OnError = (c: Context) => Response | Promise<Response>
type BodyLimitOptions = {
  maxSize: number
  onError?: OnError
}

/**
 * Body Limit Middleware for Hono.
 *
 * @see {@link https://hono.dev/docs/middleware/builtin/body-limit}
 *
 * @param {BodyLimitOptions} options - The options for the body limit middleware.
 * @param {number} options.maxSize - The maximum body size allowed.
 * @param {OnError} [options.onError] - The error handler to be invoked if the specified body size is exceeded.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.post(
 *   '/upload',
 *   bodyLimit({
 *     maxSize: 50 * 1024, // 50kb
 *     onError: (c) => {
 *       return c.text('overflow :(', 413)
 *     },
 *   }),
 *   async (c) => {
 *     const body = await c.req.parseBody()
 *     if (body['file'] instanceof File) {
 *       console.log(`Got file sized: ${body['file'].size}`)
 *     }
 *     return c.text('pass :)')
 *   }
 * )
 * ```
 */
export const bodyLimit = (options: BodyLimitOptions): MiddlewareHandler => {
  const onError: OnError =
    options.onError ||
    (() => {
      const res = new Response(ERROR_MESSAGE, {
        status: 413,
      })
      throw new HTTPException(413, { res })
    })
  const maxSize = options.maxSize

  return async function bodyLimit(c, next) {
    if (!c.req.raw.body) {
      // maybe GET or HEAD request
      return next()
    }

    const hasTransferEncoding = c.req.raw.headers.has('transfer-encoding')
    const hasContentLength = c.req.raw.headers.has('content-length')

    if (hasContentLength && !hasTransferEncoding) {
      // Only Content-Length present - we can trust it
      const contentLength = parseInt(c.req.raw.headers.get('content-length') || '0', 10)
      return contentLength > maxSize ? onError(c) : next()
    }

    // Transfer-Encoding present (chunked) or no length headers.
    // Per RFC 7230, when both are present Transfer-Encoding takes precedence
    // and Content-Length is ignored. Read the body up-front so the size check
    // is final before the handler runs, regardless of how (or whether) the
    // handler reads the body.
    let size = 0
    const chunks: Uint8Array[] = []
    const rawReader = c.req.raw.body.getReader()
    for (;;) {
      const { done, value } = await rawReader.read()
      if (done) {
        break
      }
      size += value.length
      if (size > maxSize) {
        return onError(c)
      }
      chunks.push(value)
    }

    const requestInit: RequestInit & { duplex: 'half' } = {
      body: new ReadableStream({
        start(controller) {
          for (const chunk of chunks) {
            controller.enqueue(chunk)
          }
          controller.close()
        },
      }),
      duplex: 'half',
    }
    c.req.raw = new Request(c.req.raw, requestInit as RequestInit)

    return next()
  }
}

/**
 * @module
 * Timeout Middleware for Hono.
 */

import type { Context } from '../../context'
import { HTTPException } from '../../http-exception'
import type { MiddlewareHandler } from '../../types'

export type HTTPExceptionFunction = (context: Context) => HTTPException

const defaultTimeoutException = new HTTPException(504, {
  message: 'Gateway Timeout',
})

/**
 * Timeout Middleware for Hono.
 *
 * @param {number} duration - The timeout duration in milliseconds.
 * @param {HTTPExceptionFunction | HTTPException} [exception=defaultTimeoutException] - The exception to throw when the timeout occurs. Can be a function that returns an HTTPException or an HTTPException object.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use(
 *   '/long-request',
 *   timeout(5000) // Set timeout to 5 seconds
 * )
 *
 * app.get('/long-request', async (c) => {
 *   await someLongRunningFunction()
 *   return c.text('Completed within time limit')
 * })
 * ```
 */
export const timeout = (
  duration: number,
  exception: HTTPExceptionFunction | HTTPException = defaultTimeoutException
): MiddlewareHandler => {
  return async function timeout(context, next) {
    let timer: number | undefined
    const timeoutPromise = new Promise<void>((_, reject) => {
      timer = setTimeout(() => {
        reject(typeof exception === 'function' ? exception(context) : exception)
      }, duration) as unknown as number
    })

    try {
      await Promise.race([next(), timeoutPromise])
    } finally {
      if (timer !== undefined) {
        clearTimeout(timer)
      }
    }
  }
}

import { Hono } from '../../hono'
import { bodyLimit } from '.'

const buildRequestInit = (init: RequestInit = {}): RequestInit & { duplex: 'half' } => {
  const headers: Record<string, string> = {
    'Content-Type': 'text/plain',
  }
  if (typeof init.body === 'string') {
    headers['Content-Length'] = init.body.length.toString()
  }
  return {
    method: 'POST',
    headers,
    body: null,
    ...init,
    duplex: 'half',
  }
}

describe('Body Limit Middleware', () => {
  let app: Hono

  const exampleText = 'hono is so hot' // 14byte
  const exampleText2 = 'hono is so hot and cute' // 23byte

  beforeEach(() => {
    app = new Hono()
    app.use('*', bodyLimit({ maxSize: 14 }))
    app.get('/', (c) => c.text('index'))
    app.post('/body-limit-15byte', async (c) => {
      return c.text(await c.req.raw.text())
    })
  })

  describe('GET request', () => {
    it('should return 200 response', async () => {
      const res = await app.request('/')
      expect(res).not.toBeNull()
      expect(res.status).toBe(200)
      expect(await res.text()).toBe('index')
    })
  })

  describe('POST request', () => {
    describe('string body', () => {
      it('should return 200 response', async () => {
        const res = await app.request('/body-limit-15byte', buildRequestInit({ body: exampleText }))

        expect(res).not.toBeNull()
        expect(res.status).toBe(200)
        expect(await res.text()).toBe(exampleText)
      })

      it('should return 413 response', async () => {
        const res = await app.request(
          '/body-limit-15byte',
          buildRequestInit({ body: exampleText2 })
        )

        expect(res).not.toBeNull()
        expect(res.status).toBe(413)
        expect(await res.text()).toBe('Payload Too Large')
      })
    })

    describe('ReadableStream body', () => {
      it('should return 200 response', async () => {
        const contents = ['a', 'b', 'c']
        const stream = new ReadableStream({
          start(controller) {
            while (contents.length) {
              controller.enqueue(new TextEncoder().encode(contents.shift() as string))
            }
            controller.close()
          },
        })
        const res = await app.request('/body-limit-15byte', buildRequestInit({ body: stream }))

        expect(res).not.toBeNull()
        expect(res.status).toBe(200)
        expect(await res.text()).toBe('abc')
      })

      it('should return 413 response', async () => {
        const readSpy = vi.fn().mockImplementation(() => {
          return {
            done: false,
            value: new TextEncoder().encode(exampleText),
          }
        })
        const stream = new ReadableStream()
        vi.spyOn(stream, 'getReader').mockReturnValue({
          read: readSpy,
        } as unknown as ReadableStreamDefaultReader)
        const res = await app.request('/body-limit-15byte', buildRequestInit({ body: stream }))

        expect(res).not.toBeNull()
        expect(res.status).toBe(413)
        expect(readSpy).toHaveBeenCalledTimes(2)
        expect(await res.text()).toBe('Payload Too Large')
      })
    })
  })

  describe('custom error handler', () => {
    beforeEach(() => {
      app = new Hono()
      app.post(
        '/text-limit-15byte-custom',
        bodyLimit({
          maxSize: 15,
          onError: (c) => {
            return c.text('no', 413)
          },
        }),
        (c) => {
          return c.text('yes')
        }
      )
    })

    it('should return the custom error handler', async () => {
      const res = await app.request(
        '/text-limit-15byte-custom',
        buildRequestInit({ body: exampleText2 })
      )

      expect(res).not.toBeNull()
      expect(res.status).toBe(413)
      expect(await res.text()).toBe('no')
    })
  })

  describe('Transfer-Encoding and Content-Length headers', () => {
    beforeEach(() => {
      app = new Hono()
      app.use('*', bodyLimit({ maxSize: 10 }))
      app.post('/test', async (c) => {
        return c.text(await c.req.text())
      })
    })

    it('should prioritize Transfer-Encoding over Content-Length', async () => {
      // Create a chunked body that exceeds the limit
      const largeContent = 'this is a large content that exceeds 10 bytes'
      const chunks = [largeContent.slice(0, 20), largeContent.slice(20)]

      const stream = new ReadableStream({
        start(controller) {
          chunks.forEach((chunk) => {
            controller.enqueue(new TextEncoder().encode(chunk))
          })
          controller.close()
        },
      })

      const res = await app.request('/test', {
        method: 'POST',
        headers: {
          'Content-Length': '5', // Small content-length (bypass attempt)
          'Transfer-Encoding': 'chunked', // But chunked encoding with large content
        },
        body: stream,
        duplex: 'half',
      } as RequestInit)

      // Should reject based on actual chunked content size, not Content-Length
      expect(res.status).toBe(413)
    })

    it('should handle only Content-Length header correctly', async () => {
      const smallContent = 'small'
      const res = await app.request('/test', buildRequestInit({ body: smallContent }))

      expect(res.status).toBe(200)
      expect(await res.text()).toBe(smallContent)
    })

    it('should handle only Transfer-Encoding header correctly', async () => {
      const content = 'test'
      const stream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(content))
          controller.close()
        },
      })

      const res = await app.request('/test', {
        method: 'POST',
        headers: {
          'Transfer-Encoding': 'chunked',
        },
        body: stream,
        duplex: 'half',
      } as RequestInit)

      expect(res.status).toBe(200)
      expect(await res.text()).toBe(content)
    })
  })

  describe('chunked body bypass scenarios', () => {
    const handler = vi.fn()

    const buildOversizedRequestInit = (): RequestInit & { duplex: 'half' } => ({
      method: 'POST',
      headers: { 'Transfer-Encoding': 'chunked' },
      body: new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode('1234'))
          controller.enqueue(new TextEncoder().encode('5678901234567890'))
          controller.close()
        },
      }),
      duplex: 'half',
    })

    beforeEach(() => {
      handler.mockReset()
      app = new Hono()
      app.use('*', bodyLimit({ maxSize: 8 }))
      app.post('/no-read', (c) => {
        handler()
        return c.text('NO-READ-OK')
      })
      app.post('/partial-read', async (c) => {
        handler()
        const reader = c.req.raw.body?.getReader()
        const chunk = reader ? await reader.read() : { value: undefined }
        return c.text(new TextDecoder().decode(chunk.value))
      })
      app.post('/swallow-error', async (c) => {
        handler()
        const body = c.req.raw.body
        if (!body) {
          return c.text('no body')
        }
        const reader = body.getReader()
        let seen = ''
        try {
          for (;;) {
            const { done, value } = await reader.read()
            if (done) {
              break
            }
            seen += new TextDecoder().decode(value)
          }
        } catch {
          // intentionally swallow read errors
        }
        return c.text(`processed:${seen}`)
      })
    })

    it('should reject when handler does not read the body', async () => {
      const res = await app.request('/no-read', buildOversizedRequestInit())
      expect(res.status).toBe(413)
      expect(handler).not.toHaveBeenCalled()
    })

    it('should reject when handler reads only the first chunk', async () => {
      const res = await app.request('/partial-read', buildOversizedRequestInit())
      expect(res.status).toBe(413)
      expect(handler).not.toHaveBeenCalled()
    })

    it('should reject when handler swallows body read errors', async () => {
      const res = await app.request('/swallow-error', buildOversizedRequestInit())
      expect(res.status).toBe(413)
      expect(handler).not.toHaveBeenCalled()
    })
  })
})

